  "title": "Uso de \"since\" e \"for\"",
  "rule": "Use \"since\" para o ponto inicial de uma ação e \"for\" para a duração total. O português costuma usar \"desde\" em ambos os casos, o que pode causar confusão.",
  "contrast": [
    {
      "label": "ponto de início com \"since\"",
      "example": "since 2015"
    },
    {
      "label": "duração de tempo com \"for\"",
      "example": "for two years"
    }
  ],
  "drill": [
    {
      "sentence": "I have lived in this city ___ five years.",
      "answer": "for",
      "options": [
        "for",
        "since"
      ],
      "feedback": "Use \"for\" porque \"five years\" indica a duração total do tempo."
    },
    {
      "sentence": "She has studied English ___ last year.",
      "answer": "since",
      "options": [
        "for",
        "since"
      ],
      "feedback": "Use \"since\" porque \"last year\" indica o ponto em que a ação começou."
    },
    {
      "sentence": "They have been friends ___ a long time.",
      "answer": "for",
      "options": [
        "for",
        "since"
      ],
      "feedback": "Use \"for\" porque \"a long time\" é um período de duração."
    },
    {
      "sentence": "He has worked at the company ___ Monday.",
      "answer": "since",
      "options": [
        "for",
        "since"
      ],
      "feedback": "Use \"since\" porque \"Monday\" é o ponto de partida da ação."
    },
    {
      "sentence": "We waited for the bus ___ twenty minutes.",
      "answer": "for",
      "options": [
        "for",
        "since"
      ],
      "feedback": "Use \"for\" porque \"twenty minutes\" mede a duração do tempo."
    }
  ]
}

