  "title": "Choosing between 'ser' and 'está'",
  "rule": "Use 'está' for temporary states and locations, while 'ser' is for permanent traits and jobs. English uses 'to be' for both, which can lead to mixing them up.",
  "contrast": [
    {
      "label": "Temporary state or location",
      "example": "está cansado"
    },
    {
      "label": "Permanent trait or job",
      "example": "es médica"
    }
  ],
  "drill": [
    {
      "sentence": "El café ___ muy caliente ahora.",
      "answer": "está",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Use 'está' because being hot right now is a temporary state."
    },
    {
      "sentence": "Mi padre ___ profesor de historia.",
      "answer": "es",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Use 'es' because a profession is a permanent trait."
    },
    {
      "sentence": "¿Dónde ___ las llaves de la casa?",
      "answer": "están",
      "options": [
        "son",
        "están"
      ],
      "feedback": "Use 'están' for where something is located."
    },
    {
      "sentence": "La sopa ___ fría hoy.",
      "answer": "está",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Use 'está' because the temperature of the soup is a temporary state."
    },
    {
      "sentence": "Ellos ___ personas muy amables.",
      "answer": "son",
      "options": [
        "son",
        "están"
      ],
      "feedback": "Use 'son' because being a kind person is a permanent trait."
    }
  ]
}

{
  "kind": "pattern",
