  ],
  "title": "Usando \"much\" e \"many\"",
  "rule": "Use \"many\" para contáveis e \"much\" para incontáveis. Em português usamos \"muito\" para ambos, mas o inglês separa.",
  "contrast": [
    {
      "label": "Para coisas que podemos contar",
      "example": "many chairs"
    },
    {
      "label": "Para coisas que não podemos contar",
      "example": "much time"
    }
  ],
  "drill": [
    {
      "sentence": "How ___ apples do you want?",
      "answer": "many",
      "options": [
        "many",
        "much"
      ],
      "feedback": "Use \"many\" porque podemos contar as maçãs."
    },
    {
      "sentence": "She has too ___ work to finish today.",
      "answer": "much",
      "options": [
        "many",
        "much"
      ],
      "feedback": "Use \"much\" porque trabalho é incontável em inglês."
    },
    {
      "sentence": "How ___ money do you need?",
      "answer": "much",
      "options": [
        "many",
        "much"
      ],
      "feedback": "Use \"much\" porque dinheiro é tratado como incontável."
    },
    {
      "sentence": "There are too ___ cars on the road.",
      "answer": "many",
      "options": [
        "many",
        "much"
      ],
      "feedback": "Use \"many\" porque carros são coisas que podemos contar."
    },
    {
      "sentence": "I don't have ___ patience left.",
      "answer": "much",
      "options": [
        "many",
        "much"
      ],
      "feedback": "Use \"much\" porque paciência é um substantivo incontável."
    }
  ]
}

{
  "kind": "pattern",
  "mistakeNumbers": [
