  ],
  "title": "Combining \"em\" and \"o\" into \"no\"",
  "rule": "Portuguese combines the preposition \"em\" with the articles \"o\" and \"a\" into \"no\" and \"na\". English keeps them separate, but Portuguese requires them to merge.",
  "contrast": [
    {
      "label": "Merged form for masculine singular",
      "example": "no Rio de Janeiro"
    },
    {
      "label": "Merged form for feminine singular",
      "example": "na escola"
    }
  ],
  "drill": [
    {
      "sentence": "Eu moro ___ apartamento novo.",
      "answer": "no",
      "options": [
        "no",
        "em o"
      ],
      "feedback": "Use \"no\" because \"em\" and \"o\" combine together before a masculine word."
    },
    {
      "sentence": "O gato dorme ___ cama.",
      "answer": "na",
      "options": [
        "na",
        "em a"
      ],
      "feedback": "Use \"na\" because \"em\" and \"a\" combine together before a feminine word."
    },
    {
      "sentence": "Ele trabalha ___ escritório.",
      "answer": "no",
      "options": [
        "no",
        "em o"
      ],
      "feedback": "Use \"no\" when combining \"em\" and \"o\" for masculine nouns."
    },
    {
      "sentence": "Nós estamos ___ praia hoje.",
      "answer": "na",
      "options": [
        "na",
        "em a"
      ],
      "feedback": "Use \"na\" when combining \"em\" and \"a\" for feminine nouns."
    },
    {
      "sentence": "O livro está ___ carro.",
      "answer": "no",
      "options": [
        "no",
        "em o"
      ],
      "feedback": "Use \"no\" because \"em\" plus \"o\" always merges into \"no\"."
    }
  ]
}
